  let currency = 'USD';
  let negativeStyle = 'minus';

  if (currencyOrOptions === undefined) {
    // keep defaults
  } else if (typeof currencyOrOptions === 'string') {
    currency = currencyOrOptions;
  } else if (isPlainObject(currencyOrOptions)) {
    if (currencyOrOptions.currency !== undefined) {
      currency = currencyOrOptions.currency;
    }
    if (currencyOrOptions.negativeStyle !== undefined) {
      negativeStyle = currencyOrOptions.negativeStyle;
    }
